"use client";

import {
  forwardRef,
  useCallback,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { cn } from "../../utils/cn";
import type { Themes } from "../../utils/types";
import { TreeFolderBreadcrumb } from "./TreeFolderBreadcrumb";
import { TreeFolderRow } from "./TreeFolderRow";
import { TreeFolderStyles } from "./TreeFolderStyles";
import { applyMove, descendantIds, findNode, findPath, toBreadcrumb } from "./treeFolderUtils";
import type {
  TreeFolderIconResolver,
  TreeFolderMoveArgs,
  TreeFolderNode,
  TreeFolderVisibleRow,
} from "./types";
import { useTreeFolderDnD } from "./useTreeFolderDnD";
import { DndContext, DragList } from "../../hooks/useDragDrop";

export type TreeFolderProps = {
  data: TreeFolderNode[];
  selectedId?: string | null;
  defaultSelectedId?: string | null;
  onSelectionChange?: (id: string | null) => void;

  expandedIds?: string[];
  defaultExpanded?: "all" | "roots" | "none" | string[];
  onExpandedChange?: (ids: string[]) => void;

  dndEnabled?: boolean;
  onMove?: (args: TreeFolderMoveArgs) => void;
  onDataChange?: (next: TreeFolderNode[]) => void;

  iconFor?: TreeFolderIconResolver;

  title?: string;
  showBreadcrumb?: boolean;
  showHeader?: boolean;
  highlightAncestors?: boolean;
  highlightSubtree?: boolean;
  headerAccessory?: ReactNode;
  emptyState?: ReactNode;

  rowHeight?: number;
  indent?: number;
  /** Optional. If set, the row strip will be at least this wide (in px) — useful
   *  when you want the band to extend across a wider canvas regardless of content. */
  contentMinWidth?: number;

  className?: string;
  theme?: Themes;
};

export type TreeFolderHandle = {
  selectId: (id: string | null) => void;
  expandAll: () => void;
  collapseAll: () => void;
  scrollToId: (id: string) => void;
};

const ROW_HEIGHT_DEFAULT = 28;
const INDENT_DEFAULT = 14;

function collectIds(nodes: TreeFolderNode[], out: string[] = []): string[] {
  for (const n of nodes) {
    out.push(n.id);
    if (n.children) collectIds(n.children, out);
  }
  return out;
}

function rootIds(nodes: TreeFolderNode[]): string[] {
  return nodes.map((n) => n.id);
}

function flattenVisible(data: TreeFolderNode[], expanded: Set<string>): TreeFolderVisibleRow[] {
  const out: TreeFolderVisibleRow[] = [];
  // `ancestorHasMore` tracks, for each open ancestor depth on the descent
  // path, whether that ancestor still has more siblings to render. We push
  // before descending and pop on the way back up; each row snapshots the
  // current state so its connector gutters know which verticals to draw.
  const ancestorHasMore: boolean[] = [];
  const walk = (nodes: TreeFolderNode[], level: number, parentId: string | null) => {
    nodes.forEach((node, idx) => {
      const isInternal = !!(node.children && node.children.length > 0);
      const isOpen = isInternal && expanded.has(node.id);
      const isLastChild = idx === nodes.length - 1;
      out.push({
        node,
        level,
        parentId,
        childIndex: idx,
        isOpen,
        isInternal,
        isLastChild,
        ancestorHasMoreSiblings: ancestorHasMore.slice(),
      });
      if (isOpen && node.children) {
        ancestorHasMore.push(!isLastChild);
        walk(node.children, level + 1, node.id);
        ancestorHasMore.pop();
      }
    });
  };
  walk(data, 0, null);
  return out;
}

export const TreeFolder = forwardRef<TreeFolderHandle, TreeFolderProps>(
  function TreeFolder(props, ref) {
    const {
      data,
      selectedId: controlledSelected,
      defaultSelectedId = null,
      onSelectionChange,
      expandedIds: controlledExpanded,
      defaultExpanded = "roots",
      onExpandedChange,
      dndEnabled = true,
      onMove,
      onDataChange,
      iconFor,
      title = "Layers",
      showBreadcrumb = true,
      showHeader = true,
      highlightAncestors = false,
      highlightSubtree = true,
      headerAccessory,
      emptyState,
      rowHeight = ROW_HEIGHT_DEFAULT,
      indent = INDENT_DEFAULT,
      contentMinWidth,
      className,
      theme,
    } = props;

    const scrollRef = useRef<HTMLDivElement | null>(null);

    // ---- Selection state ----
    const [internalSelected, setInternalSelected] = useState<string | null>(defaultSelectedId);
    const selectedId = controlledSelected !== undefined ? controlledSelected : internalSelected;
    const isSelectionControlled = controlledSelected !== undefined;

    // ---- Expansion state ----
    const [internalExpanded, setInternalExpanded] = useState<string[]>(() => {
      if (Array.isArray(defaultExpanded)) return defaultExpanded;
      if (defaultExpanded === "all") return collectIds(data);
      if (defaultExpanded === "none") return [];
      return rootIds(data);
    });
    const expandedIds = controlledExpanded ?? internalExpanded;
    const isExpansionControlled = controlledExpanded !== undefined;
    const expandedSet = useMemo(() => new Set(expandedIds), [expandedIds]);

    // ---- Visible rows ----
    const visibleRows = useMemo(() => flattenVisible(data, expandedSet), [data, expandedSet]);
    const rowsById = useMemo(() => {
      const m = new Map<string, TreeFolderVisibleRow>();
      for (const r of visibleRows) m.set(r.node.id, r);
      return m;
    }, [visibleRows]);

    // ---- Ancestor + subtree highlight ----
    const ancestorPath = useMemo(
      () => (selectedId ? findPath(data, selectedId) : null),
      [data, selectedId],
    );
    const ancestorIdSet = useMemo(
      () => new Set((ancestorPath ?? []).slice(0, -1).map((n) => n.id)),
      [ancestorPath],
    );
    const isAncestorFn = useCallback(
      (id: string) => highlightAncestors && ancestorIdSet.has(id),
      [highlightAncestors, ancestorIdSet],
    );

    const descendantIdSet = useMemo(() => {
      if (!highlightSubtree || !selectedId) return new Set<string>();
      const node = findNode(data, selectedId);
      if (!node) return new Set<string>();
      return descendantIds(node, false);
    }, [data, selectedId, highlightSubtree]);
    const isDescendantOfSelected = useCallback(
      (id: string) => descendantIdSet.has(id),
      [descendantIdSet],
    );

    const breadcrumbItems = useMemo(
      () => (ancestorPath ? toBreadcrumb(ancestorPath) : []),
      [ancestorPath],
    );

    // ---- Handlers ----
    const handleSelect = useCallback(
      (id: string | null) => {
        if (!isSelectionControlled) setInternalSelected(id);
        onSelectionChange?.(id);
      },
      [isSelectionControlled, onSelectionChange],
    );

    const handleToggle = useCallback(
      (id: string) => {
        const next = expandedIds.includes(id)
          ? expandedIds.filter((x) => x !== id)
          : [...expandedIds, id];
        if (!isExpansionControlled) setInternalExpanded(next);
        onExpandedChange?.(next);
      },
      [expandedIds, isExpansionControlled, onExpandedChange],
    );

    const handleMoveInternal = useCallback(
      (args: TreeFolderMoveArgs) => {
        onMove?.(args);
        if (onDataChange) onDataChange(applyMove(data, args));
      },
      [data, onMove, onDataChange],
    );

    const scrollToId = useCallback((id: string) => {
      const el = scrollRef.current?.querySelector<HTMLElement>(`[data-row-id="${CSS.escape(id)}"]`);
      el?.scrollIntoView({ block: "nearest", behavior: "smooth" });
    }, []);

    // ---- DnD ----
    const { dragIds, dropTarget, contextProps, ids } = useTreeFolderDnD({
      data,
      rowsById,
      enabled: dndEnabled,
      onMove: handleMoveInternal,
      canDrop: ({ parentId }) => {
        // Honor per-node `droppable: false` on the resolved parent.
        if (parentId == null) return true;
        const target = findNode(data, parentId);
        if (!target) return false;
        if (target.disabled || target.droppable === false) return false;
        return true;
      },
    });
    const dragIdSet = useMemo(() => new Set(dragIds), [dragIds]);

    // ---- Imperative handle ----
    useImperativeHandle(
      ref,
      () => ({
        selectId: (id: string | null) => {
          if (!isSelectionControlled) setInternalSelected(id);
          onSelectionChange?.(id);
          if (id) scrollToId(id);
        },
        expandAll: () => {
          const all = collectIds(data);
          if (!isExpansionControlled) setInternalExpanded(all);
          onExpandedChange?.(all);
        },
        collapseAll: () => {
          if (!isExpansionControlled) setInternalExpanded([]);
          onExpandedChange?.([]);
        },
        scrollToId,
      }),
      [
        data,
        isSelectionControlled,
        isExpansionControlled,
        onSelectionChange,
        onExpandedChange,
        scrollToId,
      ],
    );

    const isEmpty = data.length === 0;
    const stripStyle = contentMinWidth ? { minWidth: contentMinWidth } : undefined;

    return (
      <div
        data-theme={theme}
        className={cn(
          "flex h-full w-full flex-col bg-background-presentation-body-overlay-primary text-content-presentation-global-primary",
          className,
        )}
      >
        {showHeader && (
          <div className="px-3 py-2 border-b border-border-presentation-global-primary flex items-center justify-between gap-2 shrink-0">
            <span className="text-xs font-semibold text-content-presentation-global-secondary uppercase tracking-wide truncate">
              {title}
            </span>
            {headerAccessory}
          </div>
        )}

        {showBreadcrumb && (
          <div className="border-b border-border-presentation-global-primary shrink-0">
            <TreeFolderBreadcrumb
              items={breadcrumbItems}
              onSelect={(id) => {
                handleSelect(id);
                scrollToId(id);
              }}
            />
          </div>
        )}

        <TreeFolderStyles />
        <DndContext {...contextProps}>
          <div ref={scrollRef} role="tree" className="tf-scroll flex-1 min-h-0 overflow-auto pt-[6px]">
            {isEmpty ? (
              (emptyState ?? (
                <div className="text-xs text-content-presentation-global-tertiary p-3">
                  Nothing here yet.
                </div>
              ))
            ) : (
              <div className="min-w-max" style={stripStyle}>
                <DragList ids={ids} makeRoom={false}>
                  {visibleRows.map((row, idx) => {
                    const prevRow = visibleRows[idx - 1];
                    const nextRow = visibleRows[idx + 1];
                    const isSelected = selectedId === row.node.id;
                    const isDescendant = isDescendantOfSelected(row.node.id) && !isSelected;
                    const inBand = isSelected || isDescendant;

                    // Neighbour-aware band rounding: a row is "in-band" if it's the selected
                    // node itself or one of its descendants. The Set lookup handles deep nesting.
                    const prevInBand =
                      inBand &&
                      !!prevRow &&
                      (prevRow.node.id === selectedId || descendantIdSet.has(prevRow.node.id));
                    const nextInBand =
                      inBand &&
                      !!nextRow &&
                      (nextRow.node.id === selectedId || descendantIdSet.has(nextRow.node.id));

                    const isDragging = dragIdSet.has(row.node.id);
                    const isDropTargetInside =
                      dropTarget?.rowId === row.node.id && dropTarget.position === "inside";
                    const isDropBefore =
                      dropTarget?.rowId === row.node.id && dropTarget.position === "before";
                    const isDropAfter =
                      dropTarget?.rowId === row.node.id && dropTarget.position === "after";

                    return (
                      <TreeFolderRow
                        key={row.node.id}
                        row={row}
                        rowHeight={rowHeight}
                        indent={indent}
                        iconFor={iconFor}
                        isSelected={isSelected}
                        isAncestor={isAncestorFn(row.node.id) && !isSelected}
                        isDescendantOfSelected={isDescendant}
                        isPrevInBand={prevInBand}
                        isNextInBand={nextInBand}
                        isDragging={isDragging}
                        isDropTargetInside={isDropTargetInside}
                        isDropBefore={isDropBefore}
                        isDropAfter={isDropAfter}
                        dndEnabled={dndEnabled}
                        onSelect={handleSelect}
                        onToggle={handleToggle}
                      />
                    );
                  })}
                </DragList>
              </div>
            )}
          </div>
        </DndContext>
      </div>
    );
  },
);

"use client";

import { ChevronRight } from "lucide-react";
import { cn } from "../../utils/cn";
import type { TreeFolderBreadcrumb as BreadcrumbItems } from "./types";

type Props = {
  items: BreadcrumbItems;
  onSelect?: (id: string) => void;
  className?: string;
  maxItems?: number;
};

export function TreeFolderBreadcrumb({ items, onSelect, className, maxItems = 4 }: Props) {
  if (items.length === 0) {
    return (
      <div
        className={cn(
          "px-3 py-1.5 text-xs text-content-presentation-global-tertiary truncate",
          className,
        )}
      >
        No selection
      </div>
    );
  }

  const display =
    items.length > maxItems
      ? [items[0], { id: "__ellipsis", name: "…" }, ...items.slice(-(maxItems - 2))]
      : items;

  return (
    <nav
      aria-label="Tree path"
      className={cn(
        "px-3 py-1.5 flex items-center gap-1 text-xs text-content-presentation-global-secondary min-w-0",
        className,
      )}
    >
      <ol className="flex items-center gap-1 min-w-0 flex-1">
        {display.map((item, idx) => {
          const isLast = idx === display.length - 1;
          const isEllipsis = item.id === "__ellipsis";
          return (
            <li key={`${item.id}-${idx}`} className="flex items-center gap-1 min-w-0">
              {idx > 0 && (
                <ChevronRight className="w-3 h-3 shrink-0 text-content-presentation-global-tertiary" />
              )}
              {isEllipsis ? (
                <span className="text-content-presentation-global-tertiary">…</span>
              ) : isLast ? (
                <span
                  className="truncate text-content-presentation-global-primary font-medium"
                  title={item.name}
                >
                  {item.name}
                </span>
              ) : (
                <button
                  type="button"
                  onClick={() => onSelect?.(item.id)}
                  className="truncate hover:text-content-presentation-global-primary"
                  title={item.name}
                >
                  {item.name}
                </button>
              )}
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

"use client";

import { ChevronRight, ChevronDown, GripVertical } from "lucide-react";
import { useDragItem } from "../../hooks/useDragDrop";
import { cn } from "../../utils/cn";
import { resolveIcon } from "./icons";
import type { TreeFolderIconResolver, TreeFolderNode, TreeFolderVisibleRow } from "./types";

export type TreeFolderRowProps = {
  row: TreeFolderVisibleRow;
  rowHeight: number;
  indent: number;
  iconFor?: TreeFolderIconResolver;

  isSelected: boolean;
  isAncestor: boolean;
  isDescendantOfSelected: boolean;
  /** True when the previous visible row is part of the same selected-subtree band. */
  isPrevInBand: boolean;
  /** True when the next visible row is part of the same selected-subtree band. */
  isNextInBand: boolean;

  isDragging: boolean;
  isDropTargetInside: boolean;
  isDropBefore: boolean;
  isDropAfter: boolean;

  dndEnabled: boolean;
  onSelect: (id: string | null) => void;
  onToggle: (id: string) => void;
};

export function TreeFolderRow({
  row,
  rowHeight,
  indent,
  iconFor,
  isSelected,
  isAncestor,
  isDescendantOfSelected,
  isPrevInBand,
  isNextInBand,
  isDragging,
  isDropTargetInside,
  isDropBefore,
  isDropAfter,
  dndEnabled,
  onSelect,
  onToggle,
}: TreeFolderRowProps) {
  const { node, level, isOpen, isInternal, ancestorHasMoreSiblings } = row;

  const {
    ref: dragRef,
    handleProps: dragProps,
    style: dragStyle,
  } = useDragItem(node.id, !dndEnabled || Boolean(node.disabled), { follow: false });
  const data = node;
  const hasChildren = isInternal;

  const willReceiveDrop = isDropTargetInside && dndEnabled;
  const inSubtreeOfSelected = isDescendantOfSelected;
  const inAncestorChain = isAncestor;
  // Selected row gets the strong fill; direct children get a softer overlay so
  // they read as "members of the selected group" without competing with the
  // selection itself. Rows stand alone — no neighbor-aware joining anymore.
  const showSelected = isSelected && !willReceiveDrop;
  const showChildOfSelected = inSubtreeOfSelected && !isSelected && !willReceiveDrop;
  // A row is "in the selection group" if it's the selected node itself or a
  // descendant tinted by it. Neighbor-aware rounding then merges adjacent rows
  // into one continuous pill instead of stacked individual chips.
  const inGroup = showSelected || showChildOfSelected;
  const isGroupStart = inGroup && !isPrevInBand;
  const isGroupEnd = inGroup && !isNextInBand;

  const icon = resolveIcon(iconFor, data, {
    isOpen,
    isInternal,
    isSelected,
  });

  const outerClassName = cn(
    "relative w-full min-w-max",
    isDragging && "opacity-40",
    data.disabled && "opacity-50 pointer-events-none",
  );

  const bandClassName = cn(
    "pointer-events-none absolute inset-y-0 inset-x-[2px] z-0 rounded-md transition-colors duration-100",
    inGroup && !isGroupStart && "rounded-t-none",
    inGroup && !isGroupEnd && "rounded-b-none",
    !willReceiveDrop &&
      !inGroup &&
      "group-hover/row:bg-background-presentation-form-field-hover group-active/row:bg-background-presentation-action-hover/20",
    showSelected && "bg-background-presentation-state-information-primary",
    // Token isn't exposed as channels, so Tailwind's /alpha modifier doesn't
    // work on it — paint the descendant tint with the same hex at 30% alpha.
    showChildOfSelected && "bg-[#005ECC]/30",
    inAncestorChain && !inGroup && "bg-background-presentation-state-information-secondary",
    willReceiveDrop && "bg-background-presentation-state-information-primary",
  );

  const rowClassName = cn(
    "relative z-10 flex items-center gap-1 py-1 pr-2 cursor-pointer text-sm min-w-max",
    showSelected && "text-white",
    willReceiveDrop && "text-white",
  );

  // Grip occupies a fixed slot at the outer-left edge. `contentStart` is where
  // the indent-padding origin (depth 0) begins, leaving breathing room between
  // the grip column and the first connector / chevron.
  const gripSlotWidth = 16;
  const gripGutterPad = 6;
  const contentStart = gripSlotWidth + gripGutterPad; // 22px

  const rowStyle = {
    paddingInlineStart: contentStart + level * indent,
    height: rowHeight,
  };

  const handleRowClick = () => {
    if (data.disabled) return;
    onSelect(node.id);
  };

  // Insert lines for "between" drops (above/below sibling). Inset to the row's
  // indent so they line up with the new sibling's level.
  const insertLineInset = contentStart + level * indent;

  return (
    <div
      ref={dragRef}
      data-row-id={node.id}
      className={cn("select-none group/row", outerClassName)}
      // The row is the drag surface, not just the grip: that is how this tree has always behaved,
      // and the 8px threshold is what keeps a click on it still a click.
      style={{ ...dragStyle, height: rowHeight }}
      {...dragProps}
    >
      <span aria-hidden className={bandClassName} />

      {/* Drag handle sits in a fixed slot at the outer-left of the row so it
          never collides with the connector verticals — those start to the
          right of this 16px reserved column. Hidden until row hover. */}
      {dndEnabled && (
        <span
          className="absolute start-1.5 top-0 z-[6] flex h-full w-4 items-center justify-center opacity-0 group-hover/row:opacity-100 transition-opacity duration-150 cursor-grab active:cursor-grabbing"
          aria-hidden
        >
          <GripVertical
            className={cn(
              "w-3.5 h-3.5",
              showSelected ? "text-white/80" : "text-content-presentation-global-tertiary",
            )}
          />
        </span>
      )}

      {level > 0 && (
        <div className="pointer-events-none absolute inset-0 z-[5]">
          <TreeConnectors
            level={level}
            indent={indent}
            rowHeight={rowHeight}
            contentStart={contentStart}
            ancestorHasMoreSiblings={ancestorHasMoreSiblings}
          />
        </div>
      )}

      {isDropBefore && (
        <span
          aria-hidden
          className="pointer-events-none absolute -top-px left-0 right-0 z-20 h-0.5 bg-background-presentation-state-information-primary"
          style={{ marginInlineStart: insertLineInset }}
        />
      )}
      {isDropAfter && (
        <span
          aria-hidden
          className="pointer-events-none absolute -bottom-px left-0 right-0 z-20 h-0.5 bg-background-presentation-state-information-primary"
          style={{ marginInlineStart: insertLineInset }}
        />
      )}

      <div
        role="treeitem"
        aria-expanded={isInternal ? isOpen : undefined}
        aria-selected={isSelected}
        aria-disabled={data.disabled || undefined}
        aria-level={level + 1}
        onClick={handleRowClick}
        className={rowClassName}
        style={rowStyle}
      >
        {hasChildren ? (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              onToggle(node.id);
            }}
            className={cn(
              "shrink-0 w-4 h-4 flex items-center justify-center rounded",
              showSelected
                ? "text-white/80 hover:text-white"
                : "text-content-presentation-global-tertiary hover:text-content-presentation-global-primary",
            )}
            aria-label={isOpen ? "Collapse" : "Expand"}
          >
            {isOpen ? (
              <ChevronDown className="w-3.5 h-3.5" />
            ) : (
              <ChevronRight className="w-3.5 h-3.5" />
            )}
          </button>
        ) : (
          <span className="shrink-0 w-4 h-4" />
        )}

        <span
          className={cn(
            "shrink-0 w-4 h-4 flex items-center justify-center",
            showSelected ? "text-white/90" : "text-content-presentation-global-tertiary",
          )}
          aria-hidden
        >
          {icon}
        </span>

        <span className="whitespace-nowrap pr-2" title={data.name}>
          {data.name}
        </span>

        {/* `meta` has always been part of `TreeFolderNode` but was never painted. It sits after
            the name, before the collapsed-child count, and only appears when a node supplies it. */}
        {data.meta != null && <span className="shrink-0 pr-2">{data.meta}</span>}

        {hasChildren && !isOpen && (
          <span
            className={cn(
              "shrink-0 text-xs tabular-nums",
              showSelected ? "text-white/80" : "text-content-presentation-global-tertiary",
            )}
          >
            ({countDescendants(node)})
          </span>
        )}
      </div>
    </div>
  );
}

/**
 * Connector lines (T/L bends) aligned to where each ancestor's chevron sits in
 * the row layout, so verticals drop directly from the parent's twisty rather
 * than floating in the indent column. Geometry:
 *
 *   row paddingLeft = 4 + level * indent
 *   row content order = [grip?(16)] [chevron(16)] [icon(16)] [text]
 *
 * So the chevron of a row at depth D is centered at:
 *   chevronX(D) = 4 + D * indent + (dndEnabled ? 16 : 0) + 8
 *
 * A child at depth D+1 hangs its vertical at chevronX(D) and runs a horizontal
 * stub from there out to (paddingLeft - 2) — landing just before the child's
 * own grip/chevron. Last child renders an "L" (vertical stops at midline);
 * other siblings render a "T" (vertical runs full height). Ancestor gutters
 * keep their verticals only when that ancestor still has siblings below.
 */
function TreeConnectors({
  level,
  indent,
  rowHeight,
  contentStart,
  ancestorHasMoreSiblings,
}: {
  level: number;
  indent: number;
  rowHeight: number;
  contentStart: number;
  ancestorHasMoreSiblings: boolean[];
}) {
  // Grip handle sits in a fixed outer-left slot, so the chevron column for a
  // row at depth D is: contentStart + D*indent + chevron-half(8).
  const chevronX = (depth: number) => contentStart + depth * indent + 8;
  // Connector color is theme-aware: black/20 on default+light, white/20 on dark.
  // The dark swap relies on a `data-theme="dark"` ancestor (set by TreeFolder).
  const lineClass = "bg-black-alpha-20 [[data-theme=dark]_&]:bg-white-alpha-20";
  const segments: React.ReactNode[] = [];

  // Ancestor verticals: full-height line at each ancestor's chevron column,
  // skipped when the ancestor at that depth has no more siblings below.
  // ancestorHasMoreSiblings[d] === "ancestor at depth d still has siblings
  // below this row," so it controls whether to draw the vertical in that
  // ancestor's chevron gutter (chevronX(d)).
  for (let d = 0; d < level - 1; d++) {
    if (!ancestorHasMoreSiblings[d]) continue;
    segments.push(
      <span
        key={`v-${d}`}
        aria-hidden
        className={cn("pointer-events-none absolute top-0 bottom-0 w-px", lineClass)}
        style={{ insetInlineStart: chevronX(d) }}
      />,
    );
  }

  // Parent's gutter (depth = level - 1). T or L vertical, plus horizontal stub
  // landing just before this row's own grip/chevron starts.
  const parentDepth = level - 1;
  const parentX = chevronX(parentDepth);
  const midY = rowHeight / 2;
  const ownContentX = contentStart + level * indent + 2; // extend 4px further toward the row content

  segments.push(
    <span
      key="v-own"
      aria-hidden
      className={cn("pointer-events-none absolute w-px", lineClass)}
      style={{
        insetInlineStart: parentX,
        top: 0,
        height: "100%",
      }}
    />,
  );
  segments.push(
    <span
      key="h-own"
      aria-hidden
      className={cn("pointer-events-none absolute h-px", lineClass)}
      style={{
        insetInlineStart: parentX,
        top: midY,
        width: Math.max(4, ownContentX - parentX),
      }}
    />,
  );

  return <>{segments}</>;
}

function countDescendants(node: { children?: TreeFolderNode[] | null }): number {
  if (!node.children) return 0;
  let n = 0;
  const stack: TreeFolderNode[] = [...node.children];
  while (stack.length) {
    n++;
    const top = stack.pop();
    if (top?.children) for (const c of top.children) stack.push(c);
  }
  return n;
}

